#' Duplicati
#'
#' 
#' @param data .
#' @param vars Variabili su cui confrontare le righe: tutte quelle del
#'   questionario, tranne l'informazione cronologica dei moduli online, per
#'   trovare gli invii identici; oppure solo quelle che identificano il
#'   rispondente, come l'email o la matricola. Le righe in cui mancano tutte non
#'   si confrontano.
#' @param ignoreCase Se TRUE i testi si confrontano senza distinguere
#'   maiuscole e minuscole e senza contare gli spazi all'inizio, alla fine e
#'   quelli ripetuti.
#' @param tuto Se TRUE mostra il pannello con la descrizione dell'analisi.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riepilogo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$gruppi} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$duplicatoOV} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$riepilogo$asDF}
#'
#' \code{as.data.frame(results$riepilogo)}
#'
#' @export
duplicates <- function(
    data,
    vars,
    ignoreCase = TRUE,
    tuto = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("duplicates requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- duplicatesOptions$new(
        vars = vars,
        ignoreCase = ignoreCase,
        tuto = tuto)

    analysis <- duplicatesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

